-- Name: events dynamic_qr_enabled_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER dynamic_qr_enabled_trigger BEFORE INSERT OR UPDATE OF preshards_pool ON public.events FOR EACH ROW EXECUTE FUNCTION public.set_dynamic_qr_enabled();


